EpisodeView {
 "type": "object",
 "required": [
  "episode_id",
  "onchain_episode_id",
  "configuration_hash",
  "configuration",
  "phase",
  "posting_deadline",
  "challenge_deadline",
  "commit_deadline",
  "reveal_deadline",
  "content_hash",
  "evidence_hash",
  "content",
  "evidence",
  "jurors",
  "creator_votes",
  "challenger_votes",
  "required_votes",
  "juror_bond_wei",
  "locked_liability_wei",
  "total_deposited_wei",
  "total_credited_wei",
  "deployment"
 ],
 "properties": {
  "challenge_deadline": {
   "type": "integer",
   "format": "int64",
   "minimum": 0
  },
  "challenger_votes": {
   "type": "integer",
   "format": "int32",
   "minimum": 0
  },
  "commit_deadline": {
   "type": "integer",
   "format": "int64",
   "minimum": 0
  },
  "configuration": {
   "$ref": "#/components/schemas/RegisterEpisode"
  },
  "configuration_hash": {
   "type": "string"
  },
  "content": {
   "type": [
    "string",
    "null"
   ]
  },
  "content_hash": {
   "type": [
    "string",
    "null"
   ]
  },
  "creator_votes": {
   "type": "integer",
   "format": "int32",
   "minimum": 0
  },
  "deployment": {
   "$ref": "#/components/schemas/DeploymentView"
  },
  "episode_id": {
   "type": "string"
  },
  "evidence": {
   "type": [
    "string",
    "null"
   ]
  },
  "evidence_hash": {
   "type": [
    "string",
    "null"
   ]
  },
  "juror_bond_wei": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "jurors": {
   "type": "array",
   "items": {
    "$ref": "#/components/schemas/JurorView"
   }
  },
  "locked_liability_wei": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "onchain_episode_id": {
   "type": "string"
  },
  "phase": {
   "type": "string",
   "enum": [
    "REGISTERED",
    "OPEN",
    "COMMIT",
    "REVEAL",
    "SETTLED_CREATOR",
    "SETTLED_CHALLENGER",
    "ABORTED",
    "EXPIRED_UNCHALLENGED",
    "EXPIRED_UNFUNDED"
   ]
  },
  "posting_deadline": {
   "type": "integer",
   "format": "int64",
   "minimum": 0
  },
  "required_votes": {
   "type": "integer",
   "minimum": 0
  },
  "reveal_deadline": {
   "type": "integer",
   "format": "int64",
   "minimum": 0
  },
  "total_credited_wei": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "total_deposited_wei": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  }
 }
}
ClaimRequest {
 "type": "object",
 "required": [
  "content"
 ],
 "properties": {
  "content": {
   "type": "string"
  }
 },
 "additionalProperties": false
}
ChallengeRequest {
 "type": "object",
 "required": [
  "evidence"
 ],
 "properties": {
  "evidence": {
   "type": "string"
  }
 },
 "additionalProperties": false
}
CommitmentRequest {
 "type": "object",
 "required": [
  "verdict",
  "assessment"
 ],
 "properties": {
  "assessment": {
   "type": "string"
  },
  "verdict": {
   "$ref": "#/components/schemas/Verdict"
  }
 },
 "additionalProperties": false
}
OperationView {
 "type": "object",
 "required": [
  "operation_id",
  "episode_id",
  "actor_id",
  "kind",
  "status",
  "transaction",
  "error"
 ],
 "properties": {
  "actor_id": {
   "type": "string"
  },
  "episode_id": {
   "type": "string"
  },
  "error": {
   "type": [
    "string",
    "null"
   ]
  },
  "kind": {
   "type": "string"
  },
  "operation_id": {
   "type": "string"
  },
  "status": {
   "type": "string",
   "enum": [
    "accepted",
    "prepared",
    "submitted",
    "included",
    "confirmed",
    "reverted",
    "failed"
   ]
  },
  "transaction": {
   "oneOf": [
    {
     "type": "null"
    },
    {
     "$ref": "#/components/schemas/TransactionView"
    }
   ]
  }
 }
}
SettlementView {
 "type": "object",
 "required": [
  "episode_id",
  "outcome",
  "final_votes",
  "winner_id",
  "winner_payout",
  "juror_payouts",
  "protocol_fee",
  "forfeited_bonds",
  "refunds",
  "total_deposited",
  "total_credited",
  "deployment"
 ],
 "properties": {
  "deployment": {
   "$ref": "#/components/schemas/DeploymentView"
  },
  "episode_id": {
   "type": "string"
  },
  "final_votes": {
   "type": "object",
   "additionalProperties": {
    "$ref": "#/components/schemas/Verdict"
   },
   "propertyNames": {
    "type": "string"
   }
  },
  "forfeited_bonds": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  },
  "juror_payouts": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  },
  "outcome": {
   "type": "string",
   "enum": [
    "REGISTERED",
    "OPEN",
    "COMMIT",
    "REVEAL",
    "SETTLED_CREATOR",
    "SETTLED_CHALLENGER",
    "ABORTED",
    "EXPIRED_UNCHALLENGED",
    "EXPIRED_UNFUNDED"
   ]
  },
  "protocol_fee": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "refunds": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  },
  "total_credited": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "total_deposited": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "winner_id": {
   "type": [
    "string",
    "null"
   ]
  },
  "winner_payout": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  }
 }
}
BalancesView {
 "type": "object",
 "required": [
  "episode_id",
  "entitlements",
  "withdrawal_credits"
 ],
 "properties": {
  "entitlements": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  },
  "episode_id": {
   "type": "string"
  },
  "withdrawal_credits": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  }
 }
}
ForumSendMessage {
 "type": "object",
 "required": [
  "content"
 ],
 "properties": {
  "content": {
   "type": "string",
   "description": "Exact UTF-8, 1\u201316384 bytes and not entirely whitespace."
  },
  "round_num": {
   "type": [
    "integer",
    "null"
   ],
   "format": "int32",
   "description": "Optional caller-supplied deliberation round, not a protocol phase.",
   "minimum": 1
  }
 },
 "additionalProperties": false
}
ParticipantView {
 "type": "object",
 "required": [
  "actor_id",
  "address"
 ],
 "properties": {
  "actor_id": {
   "type": "string"
  },
  "address": {
   "type": "string"
  }
 }
}
ErrorResponse {
 "type": "object",
 "required": [
  "error"
 ],
 "properties": {
  "error": {
   "$ref": "#/components/schemas/ApiProblem"
  }
 }
}
EmptyRequest {
