}
CreateChat {
 "type": "object",
 "required": [
  "participant_ids"
 ],
 "properties": {
  "communication_prohibited": {
   "type": "boolean",
   "description": "Defaults to prohibited. Only the operator may set this to false.",
   "default": true
  },
  "history_enabled": {
   "type": "boolean",
   "default": false
  },
  "participant_ids": {
   "type": "array",
   "items": {
    "type": "string"
   },
   "maxItems": 2,
   "minItems": 2
  }
 },
 "additionalProperties": false
}
ChatView {
 "type": "object",
 "required": [
  "chat_id",
  "episode_id",
  "participant_ids",
  "history_enabled",
  "created_at_ms"
 ],
 "properties": {
  "chat_id": {
   "type": "string"
  },
  "created_at_ms": {
   "type": "integer",
   "format": "int64",
   "minimum": 0
  },
  "episode_id": {
   "type": "string"
  },
  "history_enabled": {
   "type": "boolean"
  },
  "participant_ids": {
   "type": "array",
   "items": {
    "type": "string"
   },
   "maxItems": 2,
   "minItems": 2
  }
 }
}

